<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\Tenant\Application\Policy\Allow;

use Throwable;
use Civi\Lughauth\Features\Access\Tenant\Application\Usecase\Create\TenantCreateAllowDecision;
use Civi\Lughauth\Features\Access\Tenant\Application\Usecase\Update\TenantUpdateAllowDecision;
use Civi\Lughauth\Features\Access\Tenant\Application\Usecase\Delete\TenantDeleteAllowDecision;
use Civi\Lughauth\Features\Access\Tenant\Application\Usecase\Enable\TenantEnableAllowDecision;
use Civi\Lughauth\Features\Access\Tenant\Application\Usecase\Disable\TenantDisableAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Security\AllowDecision;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class OnlyForRootAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function checkCreate(TenantCreateAllowDecision $proposal): AllowDecision
    {
        return $this->check('TenantCreateAllowDecision', $proposal);
    }
    public function checkUpdate(TenantUpdateAllowDecision $proposal): AllowDecision
    {
        return $this->check('TenantUpdateAllowDecision', $proposal);
    }
    public function checkDelete(TenantDeleteAllowDecision $proposal): AllowDecision
    {
        return $this->check('TenantDeleteAllowDecision', $proposal);
    }
    public function checkEnable(TenantEnableAllowDecision $proposal): AllowDecision
    {
        return $this->check('TenantEnableAllowDecision', $proposal);
    }
    public function checkDisable(TenantDisableAllowDecision $proposal): AllowDecision
    {
        return $this->check('TenantDisableAllowDecision', $proposal);
    }
    private function check(string $name, AllowDecision $proposal): AllowDecision
    {
        $this->logDebug("Check " . $name . " on OnlyForRootAllow Tenant");
        $span = $this->startSpan("Check " . $name . " on OnlyForRootAllow Tenant");
        try {
            $identity = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if (!(($identity->hasScope("platform:global_access") && $identity->hasRole("admin")))) {
                    $proposal->deny('Disabled if not OnlyForRoot');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
